esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bool initializedFirst) public payable {
        require(initializedFirst == false);
        bool reverted;
        c.SetMinSum(1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted == initializedFirst);
    }
    receive() external payable {}
}

