import {Test} from "forge-std/Test.sol";
import {DEP_BANK as DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(bool initializedFirst) internal {
        vm.assume(initializedFirst == false);
        bool reverted;
        try c.SetMinSum(1) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == initializedFirst);
    }

    function testFuzz_run(bool initializedFirst) public {
        _run(initializedFirst);
    }

    receive() external payable {}
}

